using System;

namespace Reactor.Networking.Rpc;

/// <summary>
/// Provides access to singleton custom rpc's.
/// </summary>
/// <typeparam name="T">The type of the custom rpc.</typeparam>
public static class Rpc<T> where T : UnsafeCustomRpc
{
    private static T? _instance;

    /// <summary>
    /// Gets an instance of <typeparamref name="T"/> rpc.
    /// </summary>
    public static T Instance
    {
        get
        {
            if (_instance == null)
            {
                throw new InvalidOperationException($"{typeof(T).FullName} isn't registered");
            }

            return _instance;
        }

        internal set
        {
            if (_instance != null)
            {
                throw new InvalidOperationException($"{typeof(T).FullName} is already registered");
            }

            _instance = value;
        }
    }
}

using System;
using System.Collections;
using System.Linq;
using System.Reflection;
using System.Reflection.Emit;
using System.Runtime.InteropServices;
using BepInEx.Unity.IL2CPP;
using HarmonyLib;
using Hazel;
using InnerNet;
using MonoMod.RuntimeDetour;
using MonoMod.Utils;
using Reactor.Networking.Serialization;
using Reactor.Utilities;

namespace Reactor.Networking.Rpc;

/// <summary>
/// Provides a custom rpc for method rpc.
/// </summary>
public class MethodRpc : UnsafeCustomRpc
{
    private delegate object HandleDelegate(InnerNetObject innerNetObject, object[] args);

    private readonly HandleDelegate _handle;

    /// <summary>
    /// Initializes a new instance of the <see cref="MethodRpc"/> class.
    /// </summary>
    /// <param name="plugin">The plugin that the rpc is attached to.</param>
    /// <param name="method">The method of the method rpc.</param>
    /// <param name="id">The id of the rpc.</param>
    /// <param name="option">The send option of the rpc.</param>
    /// <param name="localHandling">The local handling method of the rpc.</param>
    public MethodRpc(BasePlugin plugin, MethodInfo method, uint id, SendOption option, RpcLocalHandling localHandling) : base(plugin, id)
    {
        Method = method;
        LocalHandling = localHandling;
        SendOption = option;

        var parameters = method.GetParameters();

        if (method.IsStatic)
        {
            if (method.IsStatic && parameters.Length == 0)
            {
                throw new ArgumentException("Static method rpc requires at least one argument", nameof(method));
            }

            var innerNetObjectType = parameters.First().ParameterType;

            if (!typeof(InnerNetObject).IsAssignableFrom(innerNetObjectType))
            {
                throw new ArgumentException("First argument of a static method rpc has to be an InnerNetObject", nameof(method));
            }

            InnerNetObjectType = innerNetObjectType;
        }
        else
        {
            if (!typeof(InnerNetObject).IsAssignableFrom(method.DeclaringType))
            {
                throw new ArgumentException("Declaring type of an instance method rpc has to be an InnerNetObject", nameof(method));
            }

            InnerNetObjectType = method.DeclaringType;
        }

        _handle = Hook(method, parameters, method.IsStatic);
    }

    /// <summary>
    /// Initializes a new instance of the <see cref="MethodRpc"/> class.
    /// </summary>
    /// <param name="plugin">The plugin that the rpc is attached to.</param>
    /// <param name="method">The method of the method rpc.</param>
    /// <param name="id">The id of the rpc.</param>
    /// <param name="option">The send option of the rpc.</param>
    /// <param name="localHandling">The local handling method of the rpc.</param>
    /// <param name="sendImmediately">The value indicating whether the rpc should be sent immediately.</param>
    [Obsolete("Non-immediate RPCs were removed in 2025.5.20. All RPCs are immediate. Remove sendImmediately from the parameter list.")]
    public MethodRpc(BasePlugin plugin, MethodInfo method, uint id, SendOption option, RpcLocalHandling localHandling, bool sendImmediately)
        : this(plugin, method, id, option, localHandling)
    {
        SendImmediately = sendImmediately;
    }

    /// <summary>
    /// Gets the method of the method rpc.
    /// </summary>
    public MethodInfo Method { get; }

    /// <inheritdoc />
    protected internal override bool IsSingleton => false;

    /// <inheritdoc />
    public override Type InnerNetObjectType { get; }

    /// <inheritdoc />
    public override RpcLocalHandling LocalHandling { get; }

    /// <inheritdoc />
    public override SendOption SendOption { get; }

    /// <summary>
    /// Gets a value indicating whether the method rpc should be sent immediately.
    /// </summary>
    [Obsolete("Non-immediate RPCs were removed in 2025.5.20. All RPCs are immediate. This property will be removed in a future version.")]
    public bool SendImmediately { get; } = true;

    /// <inheritdoc />
    public override void UnsafeWrite(MessageWriter writer, object? data)
    {
        var args = (object[]) data!;
        MessageSerializer.Serialize(writer, args);
    }

    /// <inheritdoc />
    public override object UnsafeRead(MessageReader reader)
    {
        var parameters = Method.GetParameters();
        var args = new object[parameters.Length - 1];

        for (var i = 1; i < parameters.Length; i++)
        {
            var parameter = parameters[i];
            args[i - 1] = reader.Deserialize(parameter.ParameterType);
        }

        return args;
    }

    /// <inheritdoc />
    public override void UnsafeHandle(InnerNetObject innerNetObject, object? data)
    {
        var args = (object[]) data!;
        var result = _handle(innerNetObject, args);

        if (result is IEnumerator enumerator)
        {
            Coroutines.Start(enumerator);
        }
    }

    /// <summary>
    /// Sends this method rpc on the specified <paramref name="innerNetObject"/> with the specified <paramref name="args"/>.
    /// </summary>
    /// <param name="innerNetObject">The <see cref="InnerNetObject"/> to send the rpc on.</param>
    /// <param name="args">The arguments to serialize and send.</param>
    public void Send(InnerNetObject innerNetObject, object[] args)
    {
        UnsafeSend(innerNetObject, args);
    }

    private static readonly MethodInfo _sendMethod = AccessTools.Method(typeof(MethodRpc), nameof(Send));

    /// <summary>
    /// Hooks the <paramref name="method"/> rpc with a dynamic method that sends it.
    /// </summary>
    private HandleDelegate Hook(MethodInfo method, ParameterInfo[] parameters, bool isStatic)
    {
        var detour = new Detour(method, GenerateSender());

        // Used as target when hooking, sends the method rpc
        DynamicMethod GenerateSender()
        {
            var parameterTypes = parameters.Select(x => x.ParameterType);
            if (!isStatic) parameterTypes = parameterTypes.Prepend(InnerNetObjectType);

            var dynamicMethod = new DynamicMethod($"Sender<{method.GetID(simple: true)}>", method.ReturnType, parameterTypes.ToArray());

            if (!isStatic) dynamicMethod.DefineParameter(0, ParameterAttributes.None, "this");

            foreach (var parameter in parameters)
            {
                dynamicMethod.DefineParameter(parameter.Position + (isStatic ? 0 : 1), ParameterAttributes.None, parameter.Name);
            }

            var il = dynamicMethod.GetILGenerator();

            // :yeefuckinhaw:
            // Black magic from stackoverflow, they also said that you shouldn't do that ;)
            // Resort to Dictionary<MethodInfo, MethodRpc> if this turns out to be unreliable
            {
                var handle = GCHandle.Alloc(this);
                var ptr = GCHandle.ToIntPtr(handle);

                if (IntPtr.Size == 4)
                {
                    il.Emit(OpCodes.Ldc_I4, ptr.ToInt32());
                }
                else
                {
                    il.Emit(OpCodes.Ldc_I8, ptr.ToInt64());
                }

                il.Emit(OpCodes.Conv_I);

                // TODO Figure out why this always throws NullReferenceException on mono
                // il.Emit(OpCodes.Ldobj, typeof(MethodRpc));

                // Workaround for ^, speed seems to be the same
                il.Emit(OpCodes.Call, AccessTools.Method(typeof(GCHandle), nameof(GCHandle.FromIntPtr)));
                var temp = il.DeclareLocal(typeof(GCHandle));
                il.Emit(OpCodes.Stloc, temp);
                il.Emit(OpCodes.Ldloca, temp);
                il.Emit(OpCodes.Call, AccessTools.PropertyGetter(typeof(GCHandle), nameof(GCHandle.Target)));
            }

            il.Emit(OpCodes.Ldarg_0);

            var offset = isStatic ? 1 : 0;

            il.Emit(OpCodes.Ldc_I4, parameters.Length - offset);
            il.Emit(OpCodes.Newarr, typeof(object));

            for (var i = offset; i < parameters.Length; i++)
            {
                var parameter = parameters[i];

                il.Emit(OpCodes.Dup);
                il.Emit(OpCodes.Ldc_I4, i - offset);
                il.Emit(OpCodes.Ldarg, i + (isStatic ? 0 : 1));

                var parameterType = parameter.ParameterType;
                if (parameterType.IsValueType)
                {
                    il.Emit(OpCodes.Box, parameterType);
                }

                il.Emit(OpCodes.Stelem_Ref);
            }

            il.Emit(OpCodes.Call, _sendMethod);

            if (method.ReturnType != typeof(void))
            {
                il.Emit(OpCodes.Ldnull);
            }

            il.Emit(OpCodes.Ret);

            return dynamicMethod;
        }

        // Proxy translating object array to trampoline method args, used by MethodRpc to invoke original handling
        HandleDelegate GenerateHandler(DynamicMethod trampoline)
        {
            var dynamicMethod = new DynamicMethod($"Handler<{method.GetID(simple: true)}>", typeof(object), new[] { typeof(InnerNetObject), typeof(object[]) });
            dynamicMethod.DefineParameter(0, ParameterAttributes.None, "innerNetObject");
            dynamicMethod.DefineParameter(1, ParameterAttributes.None, "args");

            var il = dynamicMethod.GetILGenerator();

            il.Emit(OpCodes.Ldarg_0);
            il.Emit(OpCodes.Castclass, InnerNetObjectType);

            var offset = isStatic ? 1 : 0;

            for (var i = offset; i < parameters.Length; i++)
            {
                var parameter = parameters[i];

                il.Emit(OpCodes.Ldarg_1);
                il.Emit(OpCodes.Ldc_I4, i - offset);
                il.Emit(OpCodes.Ldelem_Ref);

                var parameterType = parameter.ParameterType;
                il.Emit(parameterType.IsValueType ? OpCodes.Unbox_Any : OpCodes.Castclass, parameterType);
            }

            il.Emit(OpCodes.Call, trampoline);

            if (method.ReturnType == typeof(void))
            {
                il.Emit(OpCodes.Ldnull);
            }

            il.Emit(OpCodes.Ret);

            return dynamicMethod.CreateDelegate<HandleDelegate>();
        }

        return GenerateHandler((DynamicMethod) detour.GenerateTrampoline());
    }
}

using System;
using BepInEx.Unity.IL2CPP;
using Hazel;
using InnerNet;

namespace Reactor.Networking.Rpc;

/// <summary>
/// Base type for custom rpc's but typed with generics.
/// </summary>
/// <typeparam name="TPlugin">The type of the plugin the the rpc is attached to.</typeparam>
/// <typeparam name="TInnerNetObject">The type of the <see cref="InnerNetObject"/>.</typeparam>
/// <typeparam name="TData">The type of the rpc data.</typeparam>
public abstract class CustomRpc<TPlugin, TInnerNetObject, TData> : UnsafeCustomRpc where TPlugin : BasePlugin where TInnerNetObject : InnerNetObject
{
    /// <inheritdoc />
    protected CustomRpc(TPlugin plugin, uint id) : base(plugin, id)
    {
    }

    /// <inheritdoc cref="UnsafeCustomRpc.UnsafePlugin"/>
    public TPlugin Plugin => (TPlugin) UnsafePlugin;

    /// <inheritdoc />
    public override Type InnerNetObjectType => typeof(TInnerNetObject);

    /// <inheritdoc cref="UnsafeCustomRpc.UnsafeWrite" />
    public abstract void Write(MessageWriter writer, TData? data);

    /// <inheritdoc cref="UnsafeCustomRpc.UnsafeRead" />
    public abstract TData Read(MessageReader reader);

    /// <inheritdoc cref="UnsafeCustomRpc.UnsafeHandle" />
    public abstract void Handle(TInnerNetObject innerNetObject, TData? data);

    /// <inheritdoc />
    public override void UnsafeWrite(MessageWriter writer, object? data)
    {
        Write(writer, (TData?) data);
    }

    /// <inheritdoc />
    public override object? UnsafeRead(MessageReader reader)
    {
        return Read(reader);
    }

    /// <inheritdoc />
    public override void UnsafeHandle(InnerNetObject innerNetObject, object? data)
    {
        Handle((TInnerNetObject) innerNetObject, (TData?) data);
    }

    /// <summary>
    /// Sends this custom rpc on the specified <paramref name="innerNetObject"/> with the specified <paramref name="data"/>.
    /// </summary>
    /// <param name="innerNetObject">The <see cref="InnerNetObject"/> to send the rpc on.</param>
    /// <param name="data">The data to send.</param>
    /// <param name="immediately">Whether to send it immediately.</param>
    /// <param name="ackCallback">The callback to invoke when this packet is acknowledged.</param>
    public void Send(InnerNetObject innerNetObject, TData data, bool immediately = false, Action? ackCallback = null)
    {
        UnsafeSend(innerNetObject, data, immediately, ackCallback: ackCallback);
    }

    /// <summary>
    /// Sends this custom rpc on the specified <paramref name="innerNetObject"/> with the specified <paramref name="data"/> to the specified target.
    /// </summary>
    /// <param name="innerNetObject">The <see cref="InnerNetObject"/> to send the rpc on.</param>
    /// <param name="targetClientId">Target client id, defaults to broadcast.</param>
    /// <param name="data">The data to send.</param>
    /// <param name="ackCallback">The callback to invoke when this packet is acknowledged.</param>
    public void SendTo(InnerNetObject innerNetObject, int targetClientId, TData data, Action? ackCallback = null)
    {
        UnsafeSend(innerNetObject, data, true, targetClientId, ackCallback);
    }
}

/// <summary>
/// Base type for custom rpc's but typed with generics and without any data.
/// </summary>
/// <typeparam name="TPlugin">The type of the plugin the the rpc is attached to.</typeparam>
/// <typeparam name="TInnerNetObject">The type of the <see cref="InnerNetObject"/>.</typeparam>
public abstract class CustomRpc<TPlugin, TInnerNetObject> : UnsafeCustomRpc where TPlugin : BasePlugin where TInnerNetObject : InnerNetObject
{
    /// <inheritdoc />
    protected CustomRpc(TPlugin plugin, uint id) : base(plugin, id)
    {
    }

    /// <inheritdoc cref="UnsafeCustomRpc.UnsafePlugin"/>
    public TPlugin Plugin => (TPlugin) UnsafePlugin;

    /// <inheritdoc />
    public override Type InnerNetObjectType => typeof(TInnerNetObject);

    /// <summary>
    /// Handles the rpc.
    /// </summary>
    /// <param name="innerNetObject">The <see cref="InnerNetObject"/> the rpc is being handled on.</param>
    public abstract void Handle(TInnerNetObject innerNetObject);

    /// <inheritdoc />
    public override void UnsafeWrite(MessageWriter writer, object? data)
    {
    }

    /// <inheritdoc />
    public override object? UnsafeRead(MessageReader reader)
    {
        return null;
    }

    /// <inheritdoc />
    public override void UnsafeHandle(InnerNetObject innerNetObject, object? data)
    {
        Handle((TInnerNetObject) innerNetObject);
    }

    /// <summary>
    /// Sends this custom rpc on the specified <paramref name="innerNetObject"/>.
    /// </summary>
    /// <param name="innerNetObject">The <see cref="InnerNetObject"/> to send the rpc on.</param>
    /// <param name="immediately">Whether to send it immediately.</param>
    /// <param name="ackCallback">The callback to invoke when this packet is acknowledged.</param>
    public void Send(InnerNetObject innerNetObject, bool immediately = false, Action? ackCallback = null)
    {
        UnsafeSend(innerNetObject, immediately, ackCallback: ackCallback);
    }

    /// <summary>
    /// Sends this custom rpc on the specified <paramref name="innerNetObject"/> to the specified target.
    /// </summary>
    /// <param name="innerNetObject">The <see cref="InnerNetObject"/> to send the rpc on.</param>
    /// <param name="targetClientId">Target client id, defaults to broadcast.</param>
    /// <param name="ackCallback">The callback to invoke when this packet is acknowledged.</param>
    public void SendTo(InnerNetObject innerNetObject, int targetClientId, Action? ackCallback = null)
    {
        UnsafeSend(innerNetObject, null, true, targetClientId, ackCallback);
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using HarmonyLib;
using Hazel;
using Il2CppInterop.Generator.Extensions;
using InnerNet;
using Reactor.Utilities;

namespace Reactor.Networking.Rpc;

/// <summary>
/// Manages custom rpc's.
/// </summary>
public class CustomRpcManager
{
    /// <summary>
    /// Rpc call id for the reactor's custom rpc wrapper.
    /// </summary>
    public const byte CallId = byte.MaxValue;

    private readonly List<UnsafeCustomRpc> _list = new();
    private readonly Dictionary<Type, Dictionary<Mod, Dictionary<uint, UnsafeCustomRpc>>> _map = new();

    /// <summary>
    /// Gets a list of all custom rpc's.
    /// </summary>
    public IReadOnlyList<UnsafeCustomRpc> List => _list.AsReadOnly();

    /// <summary>
    /// Registers a custom rpc.
    /// </summary>
    /// <param name="customRpc">The custom rpc to register.</param>
    public void Register(UnsafeCustomRpc customRpc)
    {
        customRpc.Manager = this;
        _list.Add(customRpc);
        _map.GetOrCreate(customRpc.InnerNetObjectType, static _ => new Dictionary<Mod, Dictionary<uint, UnsafeCustomRpc>>())
            .GetOrCreate(customRpc.Mod, static _ => new Dictionary<uint, UnsafeCustomRpc>())
            .Add(customRpc.Id, customRpc);

        if (customRpc.IsSingleton)
        {
            typeof(Rpc<>).MakeGenericType(customRpc.GetType()).GetProperty("Instance")!.SetValue(null, customRpc);
        }
    }

    /// <summary>
    /// Implementation of <see cref="InnerNetObject.HandleRpc"/> for reading and handling reactor custom rpc's.
    /// You can use this in your custom <see cref="InnerNetObject"/> to use reactor custom rpc's on it.
    /// </summary>
    /// <param name="innerNetObject">The <see cref="InnerNetObject"/> the rpc is handled on.</param>
    /// <param name="callId">The call id of the rpc.</param>
    /// <param name="reader">The <see cref="MessageReader"/> with the data of the rpc.</param>
    /// <returns>A value indicating whether the rpc was handled.</returns>
    /// <remarks>Reactor patches base game <see cref="InnerNetObject"/>s to use this.</remarks>
    public static bool HandleRpc(InnerNetObject innerNetObject, byte callId, MessageReader reader)
    {
        if (callId == CallId)
        {
            var manager = PluginSingleton<ReactorPlugin>.Instance.CustomRpcManager;
            var customRpcs = manager._map[innerNetObject.GetType()];

            var mod = reader.ReadMod();
            var id = reader.ReadPackedUInt32();

            var customRpc = customRpcs[mod][id];

            customRpc.UnsafeHandle(innerNetObject, customRpc.UnsafeRead(reader.ReadMessage()));

            return true;
        }

        return false;
    }

    [HarmonyPatch]
    internal static class HandleRpcPatch
    {
        private static List<Type> InnerNetObjectTypes { get; } = typeof(InnerNetObject).Assembly.GetTypes().Where(x => x.IsSubclassOf(typeof(InnerNetObject)) && x != typeof(LobbyBehaviour)).ToList();

        public static IEnumerable<MethodBase> TargetMethods()
        {
            return InnerNetObjectTypes.Select(x => x.GetMethod(nameof(InnerNetObject.HandleRpc), AccessTools.allDeclared)).Where(m => m != null)!;
        }

        public static bool Prefix(InnerNetObject __instance, [HarmonyArgument(0)] byte callId, [HarmonyArgument(1)] MessageReader reader)
        {
            return !HandleRpc(__instance, callId, reader);
        }
    }
}

using System;
using System.Collections.Concurrent;
using BepInEx.Unity.IL2CPP;
using HarmonyLib;
using Hazel;
using Hazel.Udp;
using Il2CppInterop.Runtime.InteropTypes.Arrays;
using InnerNet;
using Reactor.Utilities;
using Buffer = Il2CppSystem.Buffer;

namespace Reactor.Networking.Rpc;

/// <summary>
/// Base type for custom rpc's.
/// </summary>
public abstract class UnsafeCustomRpc
{
    internal CustomRpcManager? Manager { get; set; }

    /// <summary>
    /// Gets a value indicating whether the rpc is a singleton and can be used with <see cref="Rpc{T}"/>.
    /// </summary>
    protected internal virtual bool IsSingleton => true;

    /// <summary>
    /// Gets the id of the rpc.
    /// </summary>
    public uint Id { get; }

    /// <summary>
    /// Gets the plugin of the rpc.
    /// </summary>
    public BasePlugin UnsafePlugin { get; }

    /// <summary>
    /// Gets the mod of the rpc.
    /// </summary>
    public Mod Mod { get; }

    /// <summary>
    /// Gets the InnerNetObject type the rpc targets.
    /// </summary>
    public abstract Type InnerNetObjectType { get; }

    /// <summary>
    /// Gets the send option of the rpc.
    /// </summary>
    public virtual SendOption SendOption => SendOption.Reliable;

    /// <summary>
    /// Gets the local handling method of the rpc.
    /// </summary>
    public abstract RpcLocalHandling LocalHandling { get; }

    /// <summary>
    /// Initializes a new instance of the <see cref="UnsafeCustomRpc"/> class.
    /// </summary>
    /// <param name="plugin">The plugin that the rpc is attached to.</param>
    /// <param name="id">The id of the rpc.</param>
    protected UnsafeCustomRpc(BasePlugin plugin, uint id)
    {
        UnsafePlugin = plugin;
        Mod = ModList.GetByPluginType(plugin.GetType());
        Id = id;
    }

    /// <summary>
    /// Writes <paramref name="data"/> to the <paramref name="writer"/>.
    /// </summary>
    /// <param name="writer">The writer to write to.</param>
    /// <param name="data">The data to be written.</param>
    public abstract void UnsafeWrite(MessageWriter writer, object? data);

    /// <summary>
    /// Reads rpc data from the <paramref name="reader"/>.
    /// </summary>
    /// <param name="reader">The reader to read from.</param>
    /// <returns>The rpc data from the <paramref name="reader"/>.</returns>
    public abstract object? UnsafeRead(MessageReader reader);

    /// <summary>
    /// Handles rpc data.
    /// </summary>
    /// <param name="innerNetObject">The <see cref="InnerNetObject"/> the rpc is being handled on.</param>
    /// <param name="data">The data associated with the rpc.</param>
    public abstract void UnsafeHandle(InnerNetObject innerNetObject, object? data);

    /// <summary>
    /// Sends this custom rpc on the specified <paramref name="innerNetObject"/> with the specified <paramref name="data"/>.
    /// </summary>
    /// <param name="innerNetObject">The <see cref="InnerNetObject"/> to send the rpc on.</param>
    /// <param name="data">The data to send.</param>
    /// <param name="immediately">Whether to send it immediately.</param>
    /// <param name="targetClientId">Target client id, defaults to broadcast.</param>
    /// <param name="ackCallback">The callback to invoke when this packet is acknowledged.</param>
    public void UnsafeSend(InnerNetObject innerNetObject, object? data, bool immediately = false, int targetClientId = -1, Action? ackCallback = null)
    {
        ArgumentNullException.ThrowIfNull(innerNetObject);

        if (Manager == null)
        {
            throw new InvalidOperationException("Can't send unregistered CustomRpc");
        }

        if (LocalHandling == RpcLocalHandling.Before)
        {
            UnsafeHandle(innerNetObject, data);
        }

        if (immediately == false)
        {
            Warning("Non-immediate RPCs were removed in 2025.5.20! Reactor will now always send immediately!");
        }

        var writer = AmongUsClient.Instance.StartRpcImmediately(
            innerNetObject.NetId,
            CustomRpcManager.CallId,
            SendOption,
            targetClientId);

        writer.Write(Mod);
        writer.WritePacked(Id);

        writer.StartMessage(0);
        UnsafeWrite(writer, data);
        writer.EndMessage();

        if (ackCallback != null)
        {
            if (SendOption != SendOption.Reliable) throw new ArgumentException("Can't add an ack callback to unreliable rpc", nameof(ackCallback));
            AckCallbacks.TryAdd(writer, ackCallback);
        }

        AmongUsClient.Instance.FinishRpcImmediately(writer);

        if (LocalHandling == RpcLocalHandling.After)
        {
            UnsafeHandle(innerNetObject, data);
        }
    }

    private static ConcurrentDictionary<MessageWriter, Action> AckCallbacks { get; } = new(Il2CppEqualityComparer<MessageWriter>.Instance);

    [HarmonyPatch(typeof(UdpConnection), nameof(UdpConnection.Send))]
    private static class MessageAckPatch
    {
        public static bool Prefix(UdpConnection __instance, MessageWriter msg)
        {
            if (__instance._state != ConnectionState.Connected) return true;

            if (msg.SendOption == SendOption.Reliable && AckCallbacks.TryRemove(msg, out var ackCallback))
            {
                var buffer = new Il2CppStructArray<byte>(msg.Length);
                Buffer.BlockCopy(new Il2CppSystem.Array(msg.Buffer.Pointer), 0, new Il2CppSystem.Array(buffer.Pointer), 0, msg.Length);

                __instance.ResetKeepAliveTimer();

                __instance.AttachReliableID(buffer, 1, ackCallback);
                __instance.WriteBytesToConnection(buffer, buffer.Length);

                return false;
            }

            return true;
        }
    }
}

using System;
using BepInEx.Unity.IL2CPP;

namespace Reactor.Networking.Rpc;

/// <summary>
/// Shorthand for <see cref="CustomRpc{TPlugin,TInnerNetObject,TData}"/> with <see cref="PlayerControl"/> as the TInnerNetObject.
/// </summary>
/// <typeparam name="TPlugin">The type of the plugin the the rpc is attached to.</typeparam>
/// <typeparam name="TData">The type of the rpc data.</typeparam>
public abstract class PlayerCustomRpc<TPlugin, TData> : CustomRpc<TPlugin, PlayerControl, TData> where TPlugin : BasePlugin
{
    /// <inheritdoc />
    protected PlayerCustomRpc(TPlugin plugin, uint id) : base(plugin, id)
    {
    }

    /// <summary>
    /// Sends this custom rpc on the local player with the specified <paramref name="data"/>.
    /// </summary>
    /// <param name="data">The data to send.</param>
    /// <param name="immediately">Whether to send it immediately.</param>
    /// <param name="ackCallback">The callback to invoke when this packet is acknowledged.</param>
    public void Send(TData data, bool immediately = false, Action? ackCallback = null)
    {
        Send(PlayerControl.LocalPlayer, data, immediately, ackCallback);
    }

    /// <summary>
    /// Sends this custom rpc on the local player with the specified <paramref name="data"/> to the specified target.
    /// </summary>
    /// <param name="targetClientId">Target client id, defaults to broadcast.</param>
    /// <param name="data">The data to send.</param>
    /// <param name="ackCallback">The callback to invoke when this packet is acknowledged.</param>
    public void SendTo(int targetClientId, TData data, Action? ackCallback = null)
    {
        SendTo(PlayerControl.LocalPlayer, targetClientId, data, ackCallback);
    }
}

