namespace Reactor.Networking.Patches;

internal static class ClientPatches
{
    [HarmonyPatch(typeof(InnerNetClient), nameof(InnerNetClient.DisconnectInternal))]
    public static class DisconnectInternalPatch
    {
        public static void Prefix(InnerNetClient __instance, ref DisconnectReasons reason)
        {
            if (reason == DisconnectReasons.Kicked && ReactorConnection.Instance?.LastKickReason is { } lastKickReason)
            {
                reason = DisconnectReasons.Custom;
                __instance.LastCustomDisconnect = lastKickReason;
            }
        }
    }

    [HarmonyPatch]
    public static class HandleGameDataInnerPatch
    {
        public static MethodBase TargetMethod()
        {
            return Il2CppStateMachineWrapper<InnerNetClient>.GetStateMachineMoveNext(nameof(InnerNetClient.HandleGameDataInner))!;
        }

        public static bool Prefix(Il2CppObjectBase __instance, ref bool __result)
        {
            var wrapper = new Il2CppStateMachineWrapper<InnerNetClient>(__instance);

            var innerNetClient = wrapper.Instance;
            var reader = wrapper.GetParameter<MessageReader>("reader");

            if (wrapper.State != 0) return true;

            if (reader.Tag == byte.MaxValue)
            {
                var flag = (ReactorGameDataFlag) reader.ReadByte();
                switch (flag)
                {
                    case ReactorGameDataFlag.SetKickReason:
                    {
                        var reason = reader.ReadString();
                        Debug("Received SetKickReason: " + reason);
                        if (ReactorConnection.Instance != null)
                        {
                            ReactorConnection.Instance.LastKickReason = reason;
                        }

                        break;
                    }
                }

                reader.Recycle();

                __result = false;
                return false;
            }

            if (reader.Tag == (byte) GameDataTypes.SceneChangeFlag && ReactorConnection.Instance?.Syncer == Syncer.Host)
            {
                var clientId = reader.ReadPackedInt32();
                var clientData = innerNetClient.FindClientById(clientId);
                var sceneName = reader.ReadString();

                if (clientData != null && !string.IsNullOrWhiteSpace(sceneName))
                {
                    ReactorClientData? reactorClientData = null;

                    // PATCH - Read injected ReactorHandshakeC2S
                    {
                        if (reader.BytesRemaining >= ReactorHeader.Size && ReactorHeader.Read(reader))
                        {
                            ModdedHandshakeC2S.Deserialize(reader, out var mods);

                            reactorClientData = new ReactorClientData(clientData, mods);
                            ReactorClientData.Set(clientId, reactorClientData);

                            Debug("Received reactor handshake for " + clientData.PlayerName);
                        }

                        if (innerNetClient.AmHost)
                        {
                            if (reactorClientData == null && ModList.IsAnyModRequiredOnAllClients)
                            {
                                IEnumerator CoKick()
                                {
                                    var startTime = DateTimeOffset.UtcNow;
                                    string? playerName;

                                    do
                                    {
                                        yield return null;

                                        if (DateTimeOffset.UtcNow - startTime > TimeSpan.FromSeconds(2))
                                        {
                                            playerName = "(unknown)";
                                            break;
                                        }

                                        playerName = GameData.Instance.GetPlayerByClient(clientData)?.PlayerName;
                                    } while (string.IsNullOrEmpty(playerName));

                                    Warning("Kicking " + playerName + " for not having Reactor installed");

                                    const int ChatMessageLimit = 100;

                                    var chatText = $"{playerName} tried joining without the following mods:";
                                    foreach (var mod in ModList.Current.Where(m => m.IsRequiredOnAllClients))
                                    {
                                        chatText += $"\n- {mod}";
                                    }

                                    HudManager.Instance.Chat.AddChat(PlayerControl.LocalPlayer, chatText, false);

                                    if (DataManager.Settings.Multiplayer.ChatMode == QuickChatModes.FreeChatOrQuickChat)
                                    {
                                        var truncatedChatText = chatText.Length > ChatMessageLimit
                                            ? chatText[..(ChatMessageLimit - 3)] + "..."
                                            : chatText;

                                        // Write SendChat directly instead of using RpcSendChat so we can call AddChat ourselves
                                        var messageWriter = AmongUsClient.Instance.StartRpcImmediately(PlayerControl.LocalPlayer.NetId, (byte) RpcCalls.SendChat, SendOption.Reliable);
                                        messageWriter.Write(truncatedChatText);
                                        messageWriter.EndMessage();
                                    }

                                    innerNetClient.KickPlayer(clientData.Id, false);
                                }

                                innerNetClient.StartCoroutine(CoKick());
                            }
                            else if (!Mod.Validate(reactorClientData?.Mods ?? Array.Empty<Mod>(), ModList.Current, out var reason))
                            {
                                innerNetClient.KickWithReason(clientData.Id, reason);
                                __result = false;
                                return false;
                            }
                        }
                    }

                    innerNetClient.StartCoroutine(innerNetClient.CoOnPlayerChangedScene(clientData, sceneName));
                }
                else
                {
                    UnityEngine.Debug.Log($"Couldn't find client {clientId} to change scene to {sceneName}");
                    reader.Recycle();
                }

                __result = false;
                return false;
            }

            return true;
        }
    }

    [HarmonyPatch]
    public static class CoSendSceneChangePatch
    {
        public static MethodBase TargetMethod()
        {
            return Il2CppStateMachineWrapper<InnerNetClient>.GetStateMachineMoveNext(nameof(InnerNetClient.CoSendSceneChange))!;
        }

        public static bool Prefix(Il2CppObjectBase __instance, ref bool __result)
        {
            var wrapper = new Il2CppStateMachineWrapper<InnerNetClient>(__instance);

            if (ReactorConnection.Instance!.Syncer != Syncer.Host) return true;

            var innerNetClient = wrapper.Instance;
            var sceneName = wrapper.GetParameter<string>("sceneName");

            // Check for the conditions when the scene change message should be sent
            if (!innerNetClient.AmHost &&
                innerNetClient.connection.State == ConnectionState.Connected &&
                innerNetClient.ClientId >= 0)
            {
                var clientData = innerNetClient.FindClientById(innerNetClient.ClientId);
                if (clientData != null)
                {
                    var writer = MessageWriter.Get(SendOption.Reliable);
                    writer.StartMessage(Tags.GameData);
                    writer.Write(innerNetClient.GameId);
                    writer.StartMessage((byte) GameDataTypes.SceneChangeFlag);
                    writer.WritePacked(innerNetClient.ClientId);
                    writer.Write(sceneName);

                    // PATCH - Inject ReactorHandshakeC2S
                    Debug("Injecting ReactorHandshakeC2S to CoSendSceneChange");
                    ReactorHeader.Write(writer);
                    ModdedHandshakeC2S.Serialize(writer, ModList.Current);

                    writer.EndMessage();
                    writer.EndMessage();
                    innerNetClient.SendOrDisconnect(writer);
                    writer.Recycle();

                    // Create a new coroutine to let AmongUsClient handle scene changes too
                    innerNetClient.StartCoroutine(innerNetClient.CoOnPlayerChangedScene(clientData, sceneName));

                    // Cancel this coroutine
                    wrapper.State = -1;
                    __result = false;
                    return false;
                }
            }

            return true;
        }
    }

    [HarmonyPatch]
    public static class CoHandleSpawnPatch
    {
        public static MethodBase TargetMethod()
        {
            return Il2CppStateMachineWrapper<InnerNetClient>.GetStateMachineMoveNext(nameof(InnerNetClient.CoHandleSpawn))!;
        }

        public static void Postfix(Il2CppObjectBase __instance, bool __result)
        {
            if (ReactorConnection.Instance!.Syncer != Syncer.Host) return;

            var wrapper = new Il2CppStateMachineWrapper<InnerNetClient>(__instance);
            var ownerId = wrapper.GetParameter<int>("_ownerId_5__2");

            if (!__result && !AmongUsClient.Instance.AmHost && ownerId == AmongUsClient.Instance.ClientId)
            {
                var reader = wrapper.GetParameter<MessageReader>("reader");
                if (reader.BytesRemaining >= ReactorHeader.Size && ReactorHeader.Read(reader))
                {
                    ModdedHandshakeS2C.Deserialize(reader, out var serverName, out var serverVersion, out _);
                    Debug($"Host is modded ({serverName} {serverVersion})");
                }
                else
                {
                    Debug("Host is not modded");
                    if (!Mod.Validate(ModList.Current, [], out var reason))
                    {
                        AmongUsClient.Instance.DisconnectWithReason(reason);
                    }
                }
            }
        }
    }

    [HarmonyPatch(typeof(SpawnGameDataMessage), nameof(SpawnGameDataMessage.SerializeValues))]
    public static class SpawnGameDataMessagePatch
    {
        public static void Postfix(SpawnGameDataMessage __instance, MessageWriter msg)
        {
            if (ReactorConnection.Instance!.Syncer != Syncer.Host)
            {
                return;
            }

            // PATCH - Inject ReactorHandshakeS2C
            if (AmongUsClient.Instance.ClientId != __instance.ownerId && __instance.NetObjectType == Il2CppType.Of<PlayerControl>())
            {
                Debug("Injecting ReactorHandshakeS2C to WriteSpawnMessage");
                ReactorHeader.Write(msg);
                ModdedHandshakeS2C.Serialize(msg, "Among Us", Application.version, 0); // TODO
            }
        }
    }

    [HarmonyPatch(typeof(InnerNetClient), nameof(InnerNetClient.HandleMessage))]
    public static class HandleMessagePatch
    {
        public static bool Prefix(InnerNetClient __instance, [HarmonyArgument(0)] MessageReader reader)
        {
            if (__instance.NetworkMode == NetworkModes.FreePlay)
            {
                return true;
            }

            var isFirst = false;

            if (ReactorConnection.Instance!.Syncer == null)
            {
                var parentBuffer = reader.Parent.Buffer;
                var sendOption = (SendOption) parentBuffer[0];
                if (sendOption == SendOption.Reliable)
                {
                    var id = (ushort) ((parentBuffer[1] << 8) + parentBuffer[2]);
                    isFirst = id == 1;
                }
            }

            if (reader.Tag == byte.MaxValue)
            {
                var flag = (ReactorMessageFlags) reader.ReadByte();

                switch (flag)
                {
                    case ReactorMessageFlags.Handshake:
                    {
                        ModdedHandshakeS2C.Deserialize(reader, out var serverName, out var serverVersion, out var pluginCount);

                        if (isFirst)
                        {
                            Info($"Connected to a modded server ({serverName} {serverVersion}, {pluginCount} plugins)");
                            ReactorConnection.Instance.Syncer = Syncer.Server;
                        }
                        else
                        {
                            Warning("Modded handshake came in late");
                            __instance.DisconnectWithReason("Reactor handshake was sent out of order, please try connecting again.");
                        }

                        break;
                    }
                }

                return false;
            }

            if (isFirst)
            {
                ReactorConnection.Instance.Syncer = Syncer.Host;
                Warning("Server is not modded, falling back to HAAS");
            }

            return true;
        }
    }

    [HarmonyPatch(typeof(InnerNetClient), nameof(InnerNetClient.GetConnectionData))]
    public static class HandshakePatch
    {
        public static void Prefix(ref bool useDtlsLayout)
        {
            // Due to reasons currently unknown, the useDtlsLayout parameter sometimes doesn't reflect whether DTLS
            // is actually supposed to be enabled. This causes a bad handshake message and a quick disconnect.
            // The field on AmongUsClient appears to be more reliable, so override this parameter with what it is supposed to be.
            Info($"Currently using dtls: {useDtlsLayout}. Should use dtls: {AmongUsClient.Instance.useDtls}");
            useDtlsLayout = AmongUsClient.Instance.useDtls;
        }

        public static void Postfix(ref Il2CppStructArray<byte> __result)
        {
            var handshake = new MessageWriter(1000);

            handshake.Write(__result);

            ReactorHeader.Write(handshake);

            ModdedHandshakeC2S.Serialize(
                handshake,
                ModList.Current
            );

            __result = handshake.ToByteArray(true);
            handshake.Recycle();
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using BepInEx.Unity.IL2CPP;
using HarmonyLib;
using Hazel;
using Reactor.Networking.Rpc;
using Reactor.Utilities;

namespace Reactor.Networking.Attributes;

/// <summary>
/// Automatically registers a method rpc.
/// </summary>
[AttributeUsage(AttributeTargets.Method)]
public sealed class MethodRpcAttribute : Attribute
{
    private static readonly HashSet<Assembly> _registeredAssemblies = new();

    /// <summary>
    /// Gets the id of the rpc.
    /// </summary>
    public uint Id { get; }

    /// <summary>
    /// Gets or sets the send option of the rpc.
    /// </summary>
    public SendOption SendOption { get; set; } = SendOption.Reliable;

    /// <summary>
    /// Gets or sets the local handling of the rpc.
    /// </summary>
    public RpcLocalHandling LocalHandling { get; set; } = RpcLocalHandling.Before;

    /// <summary>
    /// Gets or sets a value indicating whether the rpc should be sent immediately.
    /// </summary>
    [Obsolete("Non-immediate RPCs were removed in 2025.5.20. All RPCs are immediate. This property will be removed in a future version.")]
    public bool SendImmediately { get; set; } = true;

    /// <summary>
    /// Initializes a new instance of the <see cref="MethodRpcAttribute"/> class.
    /// </summary>
    /// <param name="id">The id of the rpc.</param>
    public MethodRpcAttribute(uint id)
    {
        Id = id;
    }

    /// <summary>
    /// Registers all method rpc's annotated with <see cref="MethodRpcAttribute"/> in the specified <paramref name="assembly"/>.
    /// </summary>
    /// <remarks>This is called automatically on plugin assemblies so you probably don't need to call this.</remarks>
    /// <param name="assembly">The assembly to search.</param>
    /// <param name="plugin">The plugin to register the rpc to.</param>
    public static void Register(Assembly assembly, BasePlugin plugin)
    {
        if (_registeredAssemblies.Contains(assembly)) return;
        _registeredAssemblies.Add(assembly);

        var methods = assembly.GetTypes()
            .SelectMany(t => t.GetMethods(BindingFlags.Static | BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.Public));

        foreach (var method in methods)
        {
            var attribute = method.GetCustomAttribute<MethodRpcAttribute>();
            if (attribute == null)
            {
                continue;
            }

            try
            {
                var customRpc = new MethodRpc(plugin, method, attribute.Id, attribute.SendOption, attribute.LocalHandling);
                PluginSingleton<ReactorPlugin>.Instance.CustomRpcManager.Register(customRpc);
            }
            catch (Exception e)
            {
                Warning($"Failed to register {method.FullDescription()}: {e}");
            }
        }
    }

    internal static void Initialize()
    {
        IL2CPPChainloader.Instance.PluginLoad += (_, assembly, plugin) => Register(assembly, plugin);
    }
}

using System;
using System.Collections.Generic;
using System.Reflection;
using BepInEx.Unity.IL2CPP;
using HarmonyLib;
using Reactor.Networking.Rpc;
using Reactor.Utilities;

namespace Reactor.Networking.Attributes;

/// <summary>
/// Automatically registers a rpc.
/// </summary>
[AttributeUsage(AttributeTargets.Class)]
public sealed class RegisterCustomRpcAttribute : Attribute
{
    private static readonly HashSet<Assembly> _registeredAssemblies = new();

    /// <summary>
    /// Gets the id of the rpc.
    /// </summary>
    public uint Id { get; }

    /// <summary>
    /// Initializes a new instance of the <see cref="RegisterCustomRpcAttribute"/> class.
    /// </summary>
    /// <param name="id">The id of the rpc.</param>
    public RegisterCustomRpcAttribute(uint id)
    {
        Id = id;
    }

    /// <summary>
    /// Registers all rpc's annotated with <see cref="RegisterCustomRpcAttribute"/> in the specified <paramref name="assembly"/>.
    /// </summary>
    /// <remarks>This is called automatically on plugin assemblies so you probably don't need to call this.</remarks>
    /// <param name="assembly">The assembly to search.</param>
    /// <param name="plugin">The plugin to register the rpc to.</param>
    public static void Register(Assembly assembly, BasePlugin plugin)
    {
        if (_registeredAssemblies.Contains(assembly)) return;
        _registeredAssemblies.Add(assembly);

        foreach (var type in assembly.GetTypes())
        {
            var attribute = type.GetCustomAttribute<RegisterCustomRpcAttribute>();

            if (attribute != null)
            {
                if (!type.IsSubclassOf(typeof(UnsafeCustomRpc)))
                {
                    throw new InvalidOperationException($"Type {type.FullDescription()} has {nameof(RegisterCustomRpcAttribute)} but doesn't extend {nameof(UnsafeCustomRpc)}.");
                }

                var customRpc = (UnsafeCustomRpc) Activator.CreateInstance(type, plugin, attribute.Id)!;
                PluginSingleton<ReactorPlugin>.Instance.CustomRpcManager.Register(customRpc);
            }
        }
    }

    internal static void Initialize()
    {
        IL2CPPChainloader.Instance.PluginLoad += (_, assembly, plugin) => Register(assembly, plugin);
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using Hazel;
using Reactor.Networking.Extensions;
using UnityEngine;

namespace Reactor.Networking.Serialization;

/// <summary>
/// Provides de/serializing of objects from/into <see cref="MessageReader"/>/<see cref="MessageWriter"/>.
/// </summary>
public static class MessageSerializer
{
    private static List<UnsafeMessageConverter> MessageConverters { get; } = new();

    private static Dictionary<Type, UnsafeMessageConverter?> MessageConverterMap { get; } = new();
    private static Dictionary<Type, Type> GenericConvertersMap { get; } = new();

    internal static void ClearMaps()
    {
        MessageConverterMap.Clear();
    }

    /// <summary>
    /// Registers a MessageConverter.
    /// </summary>
    /// <param name="type">The Type of the MessageConverter to be registered.</param>
    public static void Register(Type type)
    {
        if (type.IsGenericTypeDefinition)
        {
            var baseType = type.BaseType!;

            if (!baseType.Name.Contains("MessageConverter"))
                throw new InvalidOperationException($"{type.Name} should directly inherit from MessageConverter<T>");

            var generics = baseType.GetGenericArguments();
            var param = generics[0];

            GenericConvertersMap.Add(param.GetGenericTypeDefinition(), type);
        }
        else
        {
            var messageConverter = (UnsafeMessageConverter) Activator.CreateInstance(type)!;
            MessageConverters.Add(messageConverter);
        }
    }

    /// <summary>
    /// Finds a MessageConverter for the specified <paramref name="type"/>.
    /// </summary>
    /// <param name="type">The type of an object.</param>
    /// <returns>A MessageConverter that can convert the specified <see cref="Type"/>.</returns>
    public static UnsafeMessageConverter? FindConverter(Type type)
    {
        if (!MessageConverterMap.TryGetValue(type, out var value))
        {
            value = MessageConverters.SingleOrDefault(x => x.CanConvert(type));

            if (value == null)
                return null;

            MessageConverterMap.Add(type, value);
        }

        return value;
    }

    /// <summary>
    /// Finds and builds a MessageConverter for the specified <paramref name="type"/> using a registered generic converter.
    /// </summary>
    /// <param name="type">The type of an object.</param>
    /// <returns>A MessageConverter that can convert the specified <see cref="Type"/>.</returns>
    public static UnsafeMessageConverter? FindGenericConverter(Type type)
    {
        if (MessageConverterMap.TryGetValue(type, out var value))
            return value;

        if (!type.IsGenericType)
            return null;

        var typeDef = type.GetGenericTypeDefinition();

        if (!GenericConvertersMap.TryGetValue(typeDef, out var builder))
            return null;

        var generic = builder.MakeGenericType(type.GetGenericArguments());
        value = (UnsafeMessageConverter) Activator.CreateInstance(generic)!;

        MessageConverters.Add(value);
        MessageConverterMap.Add(type, value);

        return value;
    }

    /// <summary>
    /// Serializes <paramref name="args"/> to the <paramref name="writer"/>.
    /// </summary>
    /// <param name="writer">The <see cref="MessageWriter"/> to write to.</param>
    /// <param name="args">The args to be written.</param>
    public static void Serialize(this MessageWriter writer, params object[] args)
    {
        foreach (var arg in args)
        {
            writer.Serialize(arg);
        }
    }

    /// <summary>
    /// Serializes an <paramref name="object"/> to the <paramref name="writer"/>.
    /// </summary>
    /// <param name="writer">The <see cref="MessageWriter"/> to write to.</param>
    /// <param name="object">The <see cref="object"/> to be written.</param>
    public static void Serialize(this MessageWriter writer, object @object)
    {
        switch (@object)
        {
            case int i:
                writer.WritePacked(i);
                break;
            case uint i:
                writer.WritePacked(i);
                break;
            case byte i:
                writer.Write(i);
                break;
            case float i:
                writer.Write(i);
                break;
            case sbyte i:
                writer.Write(i);
                break;
            case ushort i:
                writer.Write(i);
                break;
            case bool i:
                writer.Write(i);
                break;
            case ulong i:
                writer.Write(i);
                break;
            case long i:
                ExtraMessageExtensions.Write(writer, i); // For some reason this insists on referring the to float write method, so this is me taking precautions
                break;
            case Vector2 i:
                writer.Write(i);
                break;
            case string i:
                writer.Write(i);
                break;
            case Color i:
                writer.Write(i);
                break;
            case Color32 i:
                writer.Write(i);
                break;
            case Enum i:
                writer.Write(i);
                break;
            default:
                var type = @object.GetType();
                var converter = FindGenericConverter(type) ?? FindConverter(type);

                if (converter != null)
                    converter.UnsafeWrite(writer, @object);
                else
                    throw new NotSupportedException("Couldn't serialize " + type.Name);

                break;
        }
    }

    /// <summary>
    /// Deserializes a generic <typeparamref name="T"/> value from the <paramref name="reader"/>.
    /// </summary>
    /// <param name="reader">The <see cref="MessageReader"/> to read from.</param>
    /// <typeparam name="T">The type to be read.</typeparam>
    /// <returns>A generic <typeparamref name="T"/> value from the <paramref name="reader"/>.</returns>
    public static T Deserialize<T>(this MessageReader reader) => (T) reader.Deserialize(typeof(T));

    /// <summary>
    /// Deserializes an <see cref="object"/> of <paramref name="objectType"/> from the <paramref name="reader"/>.
    /// </summary>
    /// <param name="reader">The <see cref="MessageReader"/> to read from.</param>
    /// <param name="objectType">The <see cref="Type"/> of the object.</param>
    /// <returns>An <see cref="object"/> from the <paramref name="reader"/>.</returns>
    public static object Deserialize(this MessageReader reader, Type objectType)
    {
        if (objectType == typeof(int))
        {
            return reader.ReadPackedInt32();
        }

        if (objectType == typeof(uint))
        {
            return reader.ReadPackedUInt32();
        }

        if (objectType == typeof(byte))
        {
            return reader.ReadByte();
        }

        if (objectType == typeof(float))
        {
            return reader.ReadSingle();
        }

        if (objectType == typeof(sbyte))
        {
            return reader.ReadSByte();
        }

        if (objectType == typeof(ushort))
        {
            return reader.ReadUInt16();
        }

        if (objectType == typeof(bool))
        {
            return reader.ReadBoolean();
        }

        if (objectType == typeof(Vector2))
        {
            return reader.ReadVector2();
        }

        if (objectType == typeof(string))
        {
            return reader.ReadString();
        }

        if (objectType == typeof(ulong))
        {
            return reader.ReadUInt64();
        }

        if (objectType == typeof(long))
        {
            return reader.ReadInt64();
        }

        if (objectType == typeof(Color))
        {
            return reader.ReadColor();
        }

        if (objectType == typeof(Color32))
        {
            return reader.ReadColor32();
        }

        if (objectType.IsEnum)
        {
            return reader.ReadEnum(objectType);
        }

        var converter = FindGenericConverter(objectType) ?? FindConverter(objectType);

        if (converter != null)
        {
            return converter.UnsafeRead(reader, objectType);
        }

        throw new NotSupportedException("Couldn't deserialize " + objectType);
    }
}

using System;
using Hazel;

namespace Reactor.Networking.Serialization;

/// <summary>
/// Base type for MessageConverter's.
/// </summary>
public abstract class UnsafeMessageConverter
{
    /// <summary>
    /// Writes the <paramref name="value"/> to the <paramref name="writer"/>.
    /// </summary>
    /// <param name="writer">The <see cref="MessageWriter"/> to write to.</param>
    /// <param name="value">The value to write.</param>
    public abstract void UnsafeWrite(MessageWriter writer, object value);

    /// <summary>
    /// Reads an object of <paramref name="objectType"/> from the <paramref name="reader"/>.
    /// </summary>
    /// <param name="reader">The <see cref="MessageReader"/> to read from.</param>
    /// <param name="objectType">The type of the object being read.</param>
    /// <returns>The object read from the <paramref name="reader"/>.</returns>
    public abstract object UnsafeRead(MessageReader reader, Type objectType);

    /// <summary>
    /// Checks whether this MessageConverter can convert the specified type.
    /// </summary>
    /// <param name="objectType">The type to check.</param>
    /// <returns>A value indicating whether this MessageConverter can convert the specified type.</returns>
    public abstract bool CanConvert(Type objectType);
}

/// <summary>
/// Base type for MessageConverter's but typed with generics.
/// </summary>
/// <typeparam name="T">The type of the value being converted.</typeparam>
public abstract class MessageConverter<T> : UnsafeMessageConverter
{
    /// <inheritdoc cref="UnsafeMessageConverter.UnsafeWrite"/>
    public abstract void Write(MessageWriter writer, T value);

    /// <summary>
    /// Reads a <typeparamref name="T"/> from the <paramref name="reader"/>.
    /// </summary>
    /// <param name="reader">The <see cref="MessageReader"/> to read from.</param>
    /// <param name="objectType">The type of the object being read.</param>
    /// <returns>The object read from the <paramref name="reader"/>.</returns>
    public abstract T Read(MessageReader reader, Type objectType);

    /// <inheritdoc />
    public override bool CanConvert(Type objectType)
    {
        return typeof(T).IsAssignableFrom(objectType);
    }

    /// <inheritdoc />
    public override void UnsafeWrite(MessageWriter writer, object value) => Write(writer, (T) value);

    /// <inheritdoc />
    public override object UnsafeRead(MessageReader reader, Type objectType) => Read(reader, objectType)!;
}

using System;
using System.Collections.Generic;
using System.Reflection;
using HarmonyLib;
