namespace Reactor.Networking.Serialization;

/// <summary>
/// Provides a MessageConverter for <see cref="InnerNetObject"/>.
/// </summary>
[MessageConverter]
public class InnerNetObjectConverter : MessageConverter<InnerNetObject?>
{
    private static readonly MethodInfo _readNetObject = AccessTools.Method(typeof(MessageExtensions), nameof(MessageExtensions.ReadNetObject));
    private static readonly Dictionary<Type, Func<MessageReader, InnerNetObject?>> _readNetObjectMap = new();

    /// <summary>
    /// <see cref="MessageExtensions.ReadNetObject{T}"/> but without generics.
    /// </summary>
    /// <param name="reader">The <see cref="MessageReader"/> to read from.</param>
    /// <param name="innerNetObjectType">The type of the <see cref="InnerNetObject"/>.</param>
    /// <returns>The <see cref="InnerNetObject"/> read from the <paramref name="reader"/>.</returns>
    public static InnerNetObject? ReadNetObject(MessageReader reader, Type innerNetObjectType)
    {
        if (_readNetObjectMap.TryGetValue(innerNetObjectType, out var value))
        {
            return value(reader);
        }

        var @delegate = _readNetObject.MakeGenericMethod(innerNetObjectType).CreateDelegate<Func<MessageReader, InnerNetObject>>();
        _readNetObjectMap[innerNetObjectType] = @delegate;
        return @delegate(reader);
    }

    /// <inheritdoc />
    public override void Write(MessageWriter writer, InnerNetObject? value)
    {
        writer.WriteNetObject(value);
    }

    /// <inheritdoc />
    public override InnerNetObject? Read(MessageReader reader, Type objectType)
    {
        return ReadNetObject(reader, objectType);
    }
}

using System;
using System.Globalization;
using Hazel;
using Hazel.Udp;
using Reactor.Networking.Serialization;
using UnityEngine;

namespace Reactor.Networking.Extensions;

/// <summary>
/// Provides extension methods for <see cref="MessageWriter"/> and <see cref="MessageReader"/>.
/// </summary>
public static class ExtraMessageExtensions
{
    private const float MIN = -50f;
    private const float MAX = 50f;
    private const float DIFF = MAX - MIN;

    private static float ReverseLerp(float t)
    {
        return Mathf.Clamp01((t - MIN) / DIFF);
    }

    /// <summary>
    /// Writes a <see cref="Vector2"/> to the <paramref name="writer"/>.
    /// </summary>
    /// <param name="writer">The <see cref="MessageWriter"/> to write to.</param>
    /// <param name="value">The <see cref="Vector2"/> to write.</param>
    public static void Write(this MessageWriter writer, Vector2 value)
    {
        var x = (ushort) (ReverseLerp(value.x) * ushort.MaxValue);
        var y = (ushort) (ReverseLerp(value.y) * ushort.MaxValue);

        writer.Write(x);
        writer.Write(y);
    }

    /// <summary>
    /// Writes an Enum value to the <paramref name="writer"/>.
    /// </summary>
    /// <param name="writer">The <see cref="MessageWriter"/> to write to.</param>
    /// <param name="value">The <see cref="Enum"/> to write.</param>
    public static void Write(this MessageWriter writer, Enum value) => writer.Serialize(Convert.ChangeType(value, Enum.GetUnderlyingType(value.GetType()), CultureInfo.InvariantCulture));

    /// <summary>
    /// Writes a long value to the <paramref name="writer"/>.
    /// </summary>
    /// <param name="writer">The <see cref="MessageWriter"/> to write to.</param>
    /// <param name="value">The <see cref="long"/> to write.</param>
    public static void Write(this MessageWriter writer, long value) => writer.Write(BitConverter.GetBytes(value));

    /// <summary>
    /// Writes a color value to the <paramref name="writer"/>.
    /// </summary>
    /// <param name="writer">The <see cref="MessageWriter"/> to write to.</param>
    /// <param name="value">The <see cref="Color32"/> to write.</param>
    public static void Write(this MessageWriter writer, Color32 value)
    {
        writer.Write(value.r);
        writer.Write(value.g);
        writer.Write(value.b);
        writer.Write(value.a);
    }

    /// <summary>
    /// Reads a <see cref="Vector2"/> from the <paramref name="reader"/>.
    /// </summary>
    /// <param name="reader">The <see cref="MessageReader"/> to read from.</param>
    /// <returns>A <see cref="Vector2"/> from the <paramref name="reader"/>.</returns>
    public static Vector2 ReadVector2(this MessageReader reader)
    {
        var x = reader.ReadUInt16() / (float) ushort.MaxValue;
        var y = reader.ReadUInt16() / (float) ushort.MaxValue;

        return new Vector2(Mathf.Lerp(MIN, MAX, x), Mathf.Lerp(MIN, MAX, y));
    }

    /// <summary>
    /// Reads an enum value and casts it to the specified type from a network message.
    /// </summary>
    /// <param name="reader">The <see cref="MessageReader"/> to read from.</param>
    /// <typeparam name="T">The <see cref="Enum"/> type to convert to.</typeparam>
    /// <returns>An <see cref="Enum"/> value from the <paramref name="reader"/>.</returns>
    public static T ReadEnum<T>(this MessageReader reader) where T : struct, Enum => (T) reader.ReadEnum(typeof(T));

    /// <summary>
    /// Reads an enum value from a network message.
    /// </summary>
    /// <param name="reader">The <see cref="MessageReader"/> to read from.</param>
    /// <param name="enumType">The type of the enum.</param>
    /// <returns>The resulting enum value from the <paramref name="reader"/>.</returns>
    public static object ReadEnum(this MessageReader reader, Type enumType) => Enum.ToObject(enumType, reader.Deserialize(Enum.GetUnderlyingType(enumType)));

    /// <summary>
    /// Reads a long value from a network message.
    /// </summary>
    /// <param name="reader">The <see cref="MessageReader"/> to read from.</param>
    /// <returns>The resulting long value from the <paramref name="reader"/>.</returns>
    public static long ReadInt64(this MessageReader reader) => BitConverter.ToInt64(reader.ReadBytes(8), 0);

    /// <summary>
    /// Reads a color value from a network message.
    /// </summary>
    /// <param name="reader">The <see cref="MessageReader"/> to read from.</param>
    /// <returns>The resulting Color32 value from the <paramref name="reader"/>.</returns>
    public static Color32 ReadColor32(this MessageReader reader) => new(reader.ReadByte(), reader.ReadByte(), reader.ReadByte(), reader.ReadByte());

    /// <summary>
    /// Reads a color value from a network message.
    /// </summary>
    /// <param name="reader">The <see cref="MessageReader"/> to read from.</param>
    /// <returns>The resulting Color value from the <paramref name="reader"/>.</returns>
    public static Color ReadColor(this MessageReader reader) => new(reader.ReadSingle(), reader.ReadSingle(), reader.ReadSingle(), reader.ReadSingle());

    /// <summary>
    /// Sends a message on the <paramref name="connection"/> with an <paramref name="ackCallback"/>.
    /// </summary>
    /// <param name="connection">The connection to send the message on.</param>
    /// <param name="msg">The message to send.</param>
    /// <param name="ackCallback">The callback to invoke when this packet is acknowledged.</param>
    public static void Send(this UdpConnection connection, MessageWriter msg, Action ackCallback)
    {
        if (msg.SendOption != SendOption.Reliable)
            throw new InvalidOperationException("Message SendOption has to be Reliable.");

        var buffer = new byte[msg.Length];
        Buffer.BlockCopy(msg.Buffer, 0, buffer, 0, msg.Length);

        connection.ResetKeepAliveTimer();

        connection.AttachReliableID(buffer, 1, ackCallback);
        connection.WriteBytesToConnection(buffer, buffer.Length);
    }
}

using Hazel;
using InnerNet;

namespace Reactor.Networking.Extensions;

/// <summary>
/// Provides extension methods for <see cref="InnerNetClient"/>.
/// </summary>
public static class ClientExtensions
{
    /// <summary>
    /// Kicks a client with id equal to <paramref name="targetClientId"/> with a <paramref name="reason"/>.
    /// </summary>
    /// <param name="innerNetClient">The <see cref="InnerNetClient"/> to send the message from.</param>
    /// <param name="targetClientId">The target client's id.</param>
    /// <param name="reason">The kick reason.</param>
    internal static void KickWithReason(this InnerNetClient innerNetClient, int targetClientId, string reason)
    {
        var writer = MessageWriter.Get(SendOption.Reliable);
        writer.StartMessage(Tags.GameDataTo);
        writer.Write(innerNetClient.GameId);
        writer.WritePacked(targetClientId);
        {
            writer.StartMessage(byte.MaxValue);
            writer.Write((byte) ReactorGameDataFlag.SetKickReason);
            writer.Write(reason);
            writer.EndMessage();
        }
        writer.EndMessage();
        innerNetClient.SendOrDisconnect(writer);
        writer.Recycle();

        innerNetClient.KickPlayer(targetClientId, false);
    }

    /// <summary>
    /// Disconnects a local <see cref="InnerNetClient"/> with a custom reason.
    /// </summary>
    /// <param name="innerNetClient">The <see cref="InnerNetClient"/> to disconnect.</param>
    /// <param name="reason">The custom reason to disconnect with.</param>
    public static void DisconnectWithReason(this InnerNetClient innerNetClient, string reason)
    {
        innerNetClient.LastCustomDisconnect = reason;
        innerNetClient.HandleDisconnect(innerNetClient.LastDisconnectReason = DisconnectReasons.Custom, reason);
    }
}

using System.Collections.Generic;
using Hazel;

namespace Reactor.Networking.Messages;

internal static class ModdedHandshakeC2S
{
    public static void Serialize(MessageWriter writer, IReadOnlyCollection<Mod> mods)
    {
        writer.WritePacked(mods.Count);
        foreach (var mod in mods)
        {
            writer.Write(mod.Id);
            writer.Write(mod.Version);
            writer.Write((ushort) mod.Flags);
            if (mod.IsRequiredOnAllClients) writer.Write(mod.Name);
        }
    }

    public static void Deserialize(MessageReader reader, out Mod[] mods)
    {
        var modCount = reader.ReadPackedInt32();
        mods = new Mod[modCount];

        for (var i = 0; i < modCount; i++)
        {
            var id = reader.ReadString();
            var version = reader.ReadString();
            var flags = (ModFlags) reader.ReadUInt16();
            var name = (flags & ModFlags.RequireOnAllClients) != 0 ? reader.ReadString() : null;

            mods[i] = new Mod(id, version, flags, name);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using System.Text;
using BepInEx;
using BepInEx.Unity.IL2CPP;
using Hazel;
using Reactor.Networking.Attributes;
using Reactor.Networking.Patches;

namespace Reactor.Networking;

/// <summary>
/// Represents currently loaded mods.
/// </summary>
public static class ModList
{
    /// <summary>
    /// Gets current mods.
    /// </summary>
    public static IReadOnlyCollection<Mod> Current { get; private set; } = null!;

    private static readonly Dictionary<string, Mod> _modById = new();
    private static readonly Dictionary<Type, Mod> _modByPluginType = new();

    /// <summary>
    /// Gets a mod by it's id.
    /// </summary>
    /// <param name="id">The id of the mod.</param>
    /// <returns>The mod with the specified <paramref name="id"/>.</returns>
    public static Mod GetById(string id)
    {
        return _modById[id];
    }

    internal static Mod GetByPluginType(Type pluginType)
    {
        return _modByPluginType[pluginType];
    }

    internal static bool IsAnyModRequiredOnAllClients { get; private set; }
    internal static bool IsAnyModDisableServerAuthority { get; private set; }

    private static readonly Dictionary<uint, Mod> _modByNetId = new();
    private static readonly Dictionary<Mod, uint> _netIdByMod = new();

    internal static Mod GetByNetId(uint netId)
    {
        return _modByNetId[netId];
    }

    internal static uint GetNetId(this Mod mod)
    {
        if (!mod.IsRequiredOnAllClients) throw new ArgumentException("Cannot get a net id for a mod without RequireOnAllClients flag", nameof(mod));
        return _netIdByMod[mod];
    }

    /// <summary>
    /// Reads a <see cref="Mod"/> reference from the <paramref name="reader"/>.
    /// </summary>
    /// <param name="reader">The <see cref="MessageReader"/> to read from.</param>
    /// <returns>A <see cref="Mod"/> from the <paramref name="reader"/>.</returns>
    /// <remarks>This will try to read by net id and fallback to a regular id otherwise.</remarks>
    public static Mod ReadMod(this MessageReader reader)
    {
        var netId = reader.ReadPackedUInt32();
        if (netId > 0)
        {
            return GetByNetId(netId);
        }

        var id = reader.ReadString();
        return GetById(id);
    }

    /// <summary>
    /// Writes a <see cref="Mod"/> reference to the <paramref name="writer"/>.
    /// </summary>
    /// <param name="writer">The <see cref="MessageWriter"/> to write to.</param>
    /// <param name="value">The <see cref="Mod"/> to write.</param>
    /// <remarks>This will write the net id if <see cref="Mod.IsRequiredOnAllClients"/> is true, regular id otherwise.</remarks>
    public static void Write(this MessageWriter writer, Mod value)
    {
        if (value.IsRequiredOnAllClients)
        {
            writer.WritePacked(value.GetNetId());
        }
        else
        {
            writer.WritePacked(0);
            writer.Write(value.Id);
        }
    }

    private static void Refresh()
    {
        if (ReactorConnection.Instance != null) throw new InvalidOperationException("Can't refresh the mod list during a connection");

        Current = IL2CPPChainloader.Instance.Plugins.Values
            .Select(pluginInfo => GetById(pluginInfo.Metadata.GUID))
            .OrderByDescending(x => x.Id == ReactorPlugin.Id)
            .ThenBy(x => x.Id, StringComparer.Ordinal)
            .ToArray();

        _modByNetId.Clear();
        _netIdByMod.Clear();

        uint netId = 1;
        foreach (var mod in Current)
        {
            if (!mod.IsRequiredOnAllClients) continue;

            _modByNetId[netId] = mod;
            _netIdByMod[mod] = netId;
            netId++;
        }

        IsAnyModRequiredOnAllClients = Current.Any(m => m.IsRequiredOnAllClients);
        IsAnyModDisableServerAuthority = Current.Any(m => (m.Flags & ModFlags.DisableServerAuthority) != 0);

        var debug = new StringBuilder("Mod list:");
        foreach (var mod in Current)
        {
            debug.AppendLine();
            debug.Append(CultureInfo.InvariantCulture, $" - {mod.Id} version: {mod.Version}, flags: {mod.Flags}");
            if (mod.IsRequiredOnAllClients) debug.Append(CultureInfo.InvariantCulture, $", netId: {mod.GetNetId()}");
        }

        Debug(debug.ToString());
    }

    private static void OnPluginLoad(PluginInfo pluginInfo, BasePlugin plugin)
    {
        var pluginType = plugin.GetType();

        var mod = new Mod(
            pluginInfo.Metadata.GUID,
            pluginInfo.Metadata.Version.Clean(),
            ReactorModFlagsAttribute.GetModFlags(pluginType),
            pluginInfo.Metadata.Name
        );

        _modById[mod.Id] = mod;
        _modByPluginType[pluginType] = mod;
    }

    internal static void Initialize()
    {
        foreach (var existingPlugin in IL2CPPChainloader.Instance.Plugins.Values)
        {
            if (existingPlugin.Instance == null) continue;
            OnPluginLoad(existingPlugin, (BasePlugin) existingPlugin.Instance);
        }

        IL2CPPChainloader.Instance.PluginLoad += (pluginInfo, _, plugin) => OnPluginLoad(pluginInfo, plugin);

        IL2CPPChainloader.Instance.Finished += Refresh;
    }
}

